CREATE     VIEW [FO].[vwLedgerTrans_Aliased] AS

	SELECT 
	 LT.[RECID] AS 'REC ID'
	--,LT.[RECID] AS 'GJAE REC ID'
	,LT.[ACCOUNTDISPLAYVALUE] AS 'DDD'
	,LT.[JOURNALNUMBER] AS 'Journal No.'
	,ISNULL(LT.[SUBLEDGERVOUCHER], '') AS 'Voucher'
	,LT.DOCUMENTNUMBER AS 'Document No.'
	,CAST(LT.[ACCOUNTINGDATE] AS DATE) AS 'Accounting Date'
	--,LT.[POSTINGLAYER] AS 'Posting Layer'
	,LT.[TRANSACTIONCURRENCYCODE] AS 'Currency'
	,LT.[TRANSACTIONCURRENCYAMOUNT] AS 'Trans. Amount'
	,LT.[ACCOUNTINGCURRENCYAMOUNT] AS 'Acc. Amount'
	,LT.[REPORTINGCURRENCYAMOUNT] AS 'Rep. Amount'
	--,LT.[QUANTITY] AS 'XXXXX'
	,LT.[POSTINGTYPE] AS 'Posting Type'
	,LT.[JOURNALCATEGORY] AS 'Journal Category'
	--,LT.[ISCORRECTION] AS 'XXXXX'
	--,LT.[ISCREDIT] AS 'XXXXX'
	--,LT.[ACKNOWLEDGEMENTDATE] AS 'XXXXX'
	--,LT.[DOCUMENTDATE] AS 'XXXXX'
	--,LT.[DOCUMENTNUMBER] AS 'XXXXX'
	,LT.RICSINTERCOMPANY AS 'I/C'
	,UPPER(LT.RICSINTERIMREPORTINGENTITY) AS 'IRE'
	--,LT.[LEDGERNAME] AS 'Ledger Name'
	,LT.[MAINACCOUNT] AS 'Main Account Code'
	,LT.[TEXT] AS 'Description'
	--,LT.[ALLOCATIONLEVEL] AS 'XXXXX'
	--,LT.[PAYMENTREFERENCE] AS 'XXXXX'
	--,LT.[REASONREF] AS 'XXXXX'
	,UPPER(LT.[DATAAREAID]) AS 'Data Area'
	,LT.[RICSPRODUCTCODE] AS 'Product Code'
	,LT.[RICSPRODUCTGROUP] AS 'Product Group'
	,LT.[RICSCOSTCENTER] AS 'Cost Center Code'
	,CASE WHEN LT.[TB_Category_Code] > 10009 AND LT.[RICSCOUNTRY] IS NULL THEN 'GBR' ELSE LT.[RICSCOUNTRY] END AS 'Country Code'
	,LT.RICSPROJECT AS 'Project Code'
	,LT.TB_Category_Code AS 'TB Category Code'
	,LT.[Createdby1] AS 'Created By'
	,LT.[createddatetime1] AS 'Created Datetime'
	,LT.ACCOUNTNUM AS 'Account No.'
	,CASE --Don't apply this to TB Category Group = Revenue
		WHEN LT.[TB_Category_Code] > 10009 AND ([RICSCOSTCENTER] = 1010 OR ([RICSCOSTCENTER] = 1310 OR RICSCOSTCENTER BETWEEN 1600 AND 1720) OR lt.[RICSCOUNTRY] IS NULL) THEN 'UK&I'
		WHEN LT.[TB_Category_Code] > 10009 AND [RICSCOSTCENTER] IN (1040, 1350) THEN 'Europe'
		WHEN LT.[TB_Category_Code] > 10009 AND [RICSCOSTCENTER] IN (1030, 1340) THEN 'MEA'
		WHEN LT.[TB_Category_Code] > 10009 AND [RICSCOSTCENTER] IN (1050, 1360) THEN 'Americas'
		WHEN LT.[TB_Category_Code] > 10009 AND [RICSCOSTCENTER] IN (1060, 1370) THEN 'Greater China'
		WHEN LT.[TB_Category_Code] > 10009 AND [RICSCOSTCENTER] = 1080 THEN 'ANZ'

		WHEN LT.[TB_Category_Code] > 10009 AND ([RICSCOSTCENTER] = 1020 OR [RICSCOSTCENTER] = 1330) THEN 'South East Asia'
		WHEN LT.[TB_Category_Code] > 10009 AND [RICSCOSTCENTER] IN (1070, 1380, 6010, 6020) THEN 'South Asia'
		WHEN LT.[TB_Category_Code] <= 10009 THEN ''
		ELSE 'All'
	END AS [P&L Region]
	,LT.[SUPPLIER_ACCOUNTNUM]
FROM [synapse_fo].[LEDGERTRANS_RICS] LT
WHERE LT.[DATAAREAID] NOT IN ('RICS', 'RGRE')
